CREATE OR REPLACE FUNCTION public.actualizar_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at = pg_catalog.now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.mark_autores_resumen_dirty_on_obra()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if (new.visible_publico is distinct from old.visible_publico)
     or (new.estado is distinct from old.estado) then
    update public.autores_resumen
    set metrica_sucia = true
    where autor_id in (
      select distinct u.autor_id
      from public.perfil_metrico_unidades() u
      where u.obra_id = new.obra_id
    );
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.mark_public_data_dirty_by_atribucion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op in ('UPDATE', 'DELETE') then
    perform public.mark_public_data_dirty_for_obra(
      coalesce(
        public.resolve_obra_id_for_grupo_atribucion(old.obra_id, old.jornada_id),
        public.resolve_obra_id_for_atribucion(old.atribucion_id)
      )
    );
  end if;
  if tg_op in ('INSERT', 'UPDATE') then
    perform public.mark_public_data_dirty_for_obra(
      coalesce(
        public.resolve_obra_id_for_grupo_atribucion(new.obra_id, new.jornada_id),
        public.resolve_obra_id_for_atribucion(new.atribucion_id)
      )
    );
  end if;
  return coalesce(new, old);
end;
$function$

